185	\begin{lemma}[Relative dimension of the identity component]
186	  \label{lem:pic0_relative_dimension_genus}
187	  \lean{AlgebraicGeometry.smoothOfRelativeDimension_genus_pic0}
188	  \uses{def:genus, thm:pic_zero_dimension_equals_genus, thm:pic0_isAbelianVariety}
189	  For a smooth proper geometrically integral curve \(C/k\) whose Picard functor is
190	  representable, \(\Pic^0_{C/k}\) is smooth over \(k\) of relative dimension
191	  \(g(C)\).
192	\end{lemma}
193	
194	\begin{proof}
195	  \(\Pic^0_{C/k}\) is a smooth \(k\)-group scheme by
196	  \cref{thm:pic0_isAbelianVariety}. For a smooth group scheme over a field the
197	  relative dimension is constant and equals the dimension of the tangent space at
198	  the identity, which is \(H^1(C,\mathcal O_C)\) by
199	  \cref{thm:pic_zero_dimension_equals_genus}. Its \(k\)-dimension is \(g(C)\) by
200	  the definition of the genus (\cref{def:genus}).
201	\end{proof}
